import{_ as n,o as t,c,ah as g}from"./chunks/framework.BIVIf5h_.js";const l=JSON.parse('{"title":"Thỏa thuận","description":"","frontmatter":{"prev":{"text":"Quy trình tài sản cố định","link":"/TT133/quy-trinh/quy-trinh-tai-san-co-dinh"},"next":{"text":"Quy trình giá thành","link":"/TT133/quy-trinh/quy-trinh-gia-thanh"}},"headers":[],"relativePath":"TT133/thoa-thuan.md","filePath":"TT133/thoa-thuan.md"}'),i={name:"TT133/thoa-thuan.md"};function o(a,h,u,r,p,m){return t(),c("div",null,[...h[0]||(h[0]=[g('<h1 id="thoa-thuan" tabindex="-1">Thỏa thuận <a class="header-anchor" href="#thoa-thuan" aria-label="Permalink to “Thỏa thuận”">​</a></h1><p>Đây là thỏa thuận pháp lý giữa khách hàng với Công ty TNHH BKIT, quy định các điều khoản trong việc khách hàng sử dụng dịch vụ phần mềm quản trị doanh nghiệp hợp nhất BKIT.VN. Thỏa thuận này là hợp đồng điện tử giữa hai bên. Bằng cách nhấp chuột vào nút “đồng ý” khi đăng ký sử dụng, khách hàng đồng ý rằng các điều khoản này sẽ được áp dụng nếu khách hàng lựa chọn truy cập hoặc sử dụng dịch vụ và thao tác nhấp chuột này tương đương với việc hai bên đã ký kết hợp đồng.</p><h2 id="đieu-1-cac-thuat-ngu-su-dung-trong-thoa-thuan" tabindex="-1">Điều 1: Các thuật ngữ sử dụng trong thỏa thuận <a class="header-anchor" href="#đieu-1-cac-thuat-ngu-su-dung-trong-thoa-thuan" aria-label="Permalink to “Điều 1: Các thuật ngữ sử dụng trong thỏa thuận”">​</a></h2><p><strong>1.1. Phần mềm:</strong> Phần mềm Quản trị doanh nghiệp hợp nhất mang tên BKIT.VN do BKIT cung cấp.</p><p><strong>1.2. Hệ thống:</strong> Bao gồm các máy chủ đặt tại trung tâm dữ liệu của BKIT, được cài đặt các phần mềm hệ thống và phần mềm BKIT.VN.</p><p><strong>1.3. BKIT:</strong> Là Công ty Cổ phần BKIT, nhà cung cấp dịch vụ phần mềm BKIT.VN.</p><p><strong>1.4. Khách hàng:</strong> Là tổ chức hoặc cá nhân đứng ra đăng ký dùng thử hoặc trả tiền sử dụng dịch vụ phần mềm BKIT.VN.</p><p><strong>1.5. Phí thuê bao dung lượng hàng năm:</strong> Là khoản phí mà khách hàng thanh toán cho BKIT để duy trì sử dụng phần mềm theo gói dung lượng đã mua. Khoản phí này được tính hàng năm và khách hàng có thể thanh toán trước cho nhiều năm ngay khi ký hợp đồng.</p><p><strong>1.6. Phí kích hoạt và sử dụng nghiệp vụ năm đầu tiên:</strong> Là khoản phí mà khách hàng thanh toán cho BKIT để kích hoạt và sử dụng nghiệp vụ cho năm đầu tiên.</p><p><strong>1.7. Phí sử dụng nghiệp vụ từ năm thứ hai:</strong> Là khoản phí mà khách hàng thanh toán cho BKIT để sử dụng nghiệp vụ đã được kích hoạt. Khoản phí này được tính từ năm thứ hai trở đi và khách hàng có thể thanh toán trước cho nhiều năm ngay khi ký hợp đồng.</p><p><strong>1.8. Phí kích hoạt chi nhánh:</strong> Là khoản phí mà khách hàng thanh toán cho BKIT để kích hoạt thêm chi nhánh mới lần đầu tiên khi bắt đầu sử dụng.</p><p><strong>1.9. Năm sử dụng:</strong> Là khoảng thời gian đủ 12 tháng tính từ thời điểm khách hàng nhận được thông tin truy cập hệ thống phần mềm BKIT.VN.</p><p><strong>1.10. Thời gian thuê bao:</strong> Là khoảng thời gian khách hàng được cấp quyền sử dụng dịch vụ phần mềm BKIT.VN theo yêu cầu đăng ký và thỏa thuận thanh toán phí với BKIT.</p><p><strong>1.11. Gia hạn thuê bao:</strong> Là việc BKIT cấp thêm thời gian sử dụng dịch vụ phần mềm BKIT.VN cho khách hàng theo thỏa thuận của hai bên.</p><p><strong>1.12. Gia hạn nghiệp vụ:</strong> Là việc BKIT cấp thêm thời gian sử dụng nghiệp vụ trên phần mềm BKIT.VN cho khách hàng theo thỏa thuận của hai bên.</p><p><strong>1.13. Thông tin phái sinh:</strong> Là các thông tin được tổng hợp, suy luận từ các thông tin gốc do khách hàng tạo ra trong phần mềm của BKIT. Ví dụ: Thông tin phái sinh từ phần mềm kế toán cá nhân có thể là Báo cáo về thu nhập trung bình của người Việt Nam, chi tiêu trung bình hàng tháng…</p><h2 id="đieu-2-quyen-su-dung-phan-mem" tabindex="-1">Điều 2: Quyền sử dụng phần mềm <a class="header-anchor" href="#đieu-2-quyen-su-dung-phan-mem" aria-label="Permalink to “Điều 2: Quyền sử dụng phần mềm”">​</a></h2><p><strong>2.1.</strong> Khách hàng có quyền sử dụng đầy đủ các tính năng của các nghiệp vụ đã kích hoạt trong thời gian nghiệp vụ và thuê bao còn hạn sử dụng. Số năm sử dụng tùy theo đăng ký mua dịch vụ của khách hàng.</p><p><strong>2.2.</strong> Đối với mỗi thuê bao khách hàng đã đăng ký và thanh toán tiền sử dụng thì sẽ được cấp một tên miền theo đăng ký của khách hàng để khách hàng sử dụng và chứa dữ liệu của khách hàng. Trường hợp khách hàng muốn thay đổi lại tên miền khác thì khách hàng sẽ làm đề nghị đổi tên miền theo quy định của BKIT. Sau khi cấp tên miền mới, BKIT sẽ cắt thuê bao của tên miền cũ để đảm bảo mỗi thuê bao của khách hàng chỉ có một tên miền duy nhất được duy trì.</p><p><strong>2.3.</strong> Khách hàng không được phép sử dụng dịch vụ phần mềm bao gồm nhưng không giới hạn bởi việc cập nhật dữ liệu, gửi email, viết bài hoặc truyền tải dữ liệu với mục đích sau:</p><ul><li>Làm tổn hại, làm phiền cho người khác hoặc gây ra thương tổn đến con người và tài sản;</li><li>Liên quan đến việc công bố các thông tin hoặc tài liệu lừa đảo, gây mất uy tín danh dự, quấy rối hoặc mang tính khiêu dâm;</li><li>Xâm phạm các quyền riêng tư hoặc kì thị chủng tộc, tôn giáo, giới tính, người tàn tật;</li><li>Xâm phạm quyền sở hữu trí tuệ hoặc các quyền sở hữu khác;</li><li>Cản trở hoặc phá hỏng Dịch vụ (bao gồm nhưng không giới hạn bởi việc truy cập Dịch vụ thông qua bất cứ phương tiện máy móc, phần mềm);</li><li>Vi phạm quy định của pháp luật.</li></ul><p><strong>2.4.</strong> Khi hết hạn thuê bao, khách hàng sẽ không được đăng nhập để sử dụng phần mềm.</p><p><strong>2.5.</strong> Khi hết hạn sử dụng nghiệp vụ, khách hàng sẽ không được sử dụng nghiệp vụ đã hết hạn.</p><p><strong>2.6.</strong> Khi hết dung lượng nhưng thời gian sử dụng vẫn còn, khách hàng có thể thực hiện việc xóa, sửa dữ liệu nhưng không được nhập thêm dữ liệu vào phần mềm. Trường hợp khách hàng xóa bớt dữ liệu đã nhập thì mới có thể nhập thêm được dữ liệu bằng đúng số dung lượng đã xóa.</p><p><strong>2.7.</strong> Khi thuê bao quá hạn trên 30 ngày, nếu khách hàng chưa làm thủ tục đăng ký và thanh toán tiền gia hạn thuê bao thì BKIT sẽ làm thủ tục cắt thuê bao. Khách hàng sẽ không sử dụng được phần mềm sau khi BKIT đã cắt thuê bao.</p><p><strong>2.8.</strong> Khi thực hiện cắt thuê bao sử dụng phần mềm, BKIT sẽ thông báo qua email trong trường hợp:</p><ul><li>Khách hàng không làm thủ tục đăng ký gia hạn, thanh toán với BKIT nếu thuê bao quá hạn sử dụng trên 30 ngày;</li><li>Khách hàng yêu cầu cắt thuê bao phần mềm;</li><li>Khách hàng vi phạm mục đích sử dụng phần mềm được nêu trong thỏa thuận này;</li><li>Khách hàng vi phạm pháp luật và cơ quan công quyền yêu cầu BKIT dừng cung cấp dịch vụ thuê bao cho khách hàng.</li></ul><h2 id="đieu-3-gia-ca-va-phuong-thuc-thanh-toan" tabindex="-1">Điều 3: Giá cả và phương thức thanh toán <a class="header-anchor" href="#đieu-3-gia-ca-va-phuong-thuc-thanh-toan" aria-label="Permalink to “Điều 3: Giá cả và phương thức thanh toán”">​</a></h2><p><strong>3.1.</strong> Phí kích hoạt và sử dụng nghiệp vụ năm đầu tiên, phí kích hoạt chi nhánh, phí sử dụng nghiệp vụ từ năm thứ hai trở đi và phí thuê bao dung lượng hàng năm mà khách hàng thanh toán cho BKIT sẽ được BKIT gửi thông báo trên chính phần mềm BKIT.VN.</p><p><strong>3.2.</strong> Khách hàng chịu trách nhiệm thanh toán cho BKIT 100% giá trị của gói sản phẩm/dịch vụ mà khách hàng chọn mua ngay sau khi khách hàng gửi đơn đặt hàng cho BKIT.</p><p><strong>3.3.</strong> Việc thanh toán các năm tiếp theo sau khi hết hạn phải được thực hiện chậm nhất là 30 ngày kể từ ngày khách hàng nhận được thông báo của BKIT về việc đóng phí và mức phí thuê bao cần đóng cho năm tiếp theo. Thông báo này được gửi trực tiếp trên chính phần mềm BKIT.VN mà khách hàng đang sử dụng.</p><p><strong>3.4.</strong> Hàng năm, BKIT có quyền điều chỉnh mức phí kích hoạt và sử dụng nghiệp vụ năm đầu tiên, phí kích hoạt chi nhánh, phí sử dụng nghiệp vụ từ năm thứ hai trở đi, phí thuê bao dung lượng hàng năm theo giá thị trường và công bố trực tiếp trên website BKIT.com.vn. Trong trường hợp Khách hàng đã thanh toán trước phí sử dụng nghiệp vụ từ năm thứ hai trở đi và phí thuê bao dung lượng hàng năm nhiều năm thì mức phí sử dụng nghiệp từ năm thứ hai trở đi, thuê bao dung lượng hàng năm sẽ không thay đổi trong suốt thời hạn thuê bao mà Khách hàng đã thanh toán.</p><p><strong>3.5.</strong> Khách hàng chịu trách nhiệm thanh toán cho BKIT bằng tiền mặt, chuyển khoản hoặc thanh toán trực tuyến thông qua ngân hàng hoặc đối tác thứ ba. Trường hợp thanh toán bằng tiền mặt, khách hàng chỉ thanh toán cho cán bộ của BKIT khi có đủ giấy tờ: Giấy giới thiệu của Công ty/Văn phòng đại diện Công ty Cổ phần BKIT về việc nhận tiền mặt (có ghi rõ số tiền), thẻ nhân viên, chứng minh nhân dân của người được ghi trong giấy giới thiệu.</p><p><strong>3.6.</strong> BKIT không chấp nhận hoàn trả bất kể chi phí nào mà khách hàng đã thanh toán cho BKIT sau khi BKIT đã hoàn thành nghĩa vụ bàn giao sản phẩm, dịch vụ cho khách hàng.</p><h2 id="đieu-4-ban-giao-san-pham-dich-vu" tabindex="-1">Điều 4: Bàn giao sản phẩm, dịch vụ <a class="header-anchor" href="#đieu-4-ban-giao-san-pham-dich-vu" aria-label="Permalink to “Điều 4: Bàn giao sản phẩm, dịch vụ”">​</a></h2><p><strong>4.1.</strong> BKIT chịu trách nhiệm bàn giao cho khách hàng quyền sử dụng phần mềm trong vòng 07 ngày sau khi khách hàng hoàn thành nghĩa vụ thanh toán cho BKIT.</p><p><strong>4.2.</strong> Khách hàng chịu trách nhiệm đăng nhập vào phần mềm để kiểm tra thời hạn sử dụng theo thông tin truy cập do BKIT gửi thông báo qua email. Khi khách hàng đăng nhập vào phần mềm thì xem như BKIT đã hoàn thành nghĩa vụ bàn giao sản phẩm và việc tính phí bắt đầu từ thời điểm này.</p><p><strong>4.3.</strong> Khách hàng chịu trách nhiệm chuẩn bị đầy đủ thiết bị, nhân lực và đường truyền theo đúng khuyến cáo của BKIT ghi trong phần mềm để tổ chức khai thác, vận hành hệ thống phần mềm.</p><p><strong>4.4.</strong> Khách hàng chịu trách nhiệm tiếp nhận, sử dụng phần mềm đúng theo hướng dẫn và khuyến cáo sử dụng của BKIT công bố trong phần mềm.</p><p><strong>4.5.</strong> Khi tiếp nhận bàn giao tài khoản truy cập từ BKIT, khách hàng có trách nhiệm thay đổi mật khẩu ngầm định ngay trong lần đầu tiên sử dụng phần mềm.</p><h2 id="đieu-5-tu-van-va-ho-tro-khach-hang" tabindex="-1">Điều 5: Tư vấn và hỗ trợ khách hàng <a class="header-anchor" href="#đieu-5-tu-van-va-ho-tro-khach-hang" aria-label="Permalink to “Điều 5: Tư vấn và hỗ trợ khách hàng”">​</a></h2><p><strong>5.1.</strong> BKIT chịu trách nhiệm cung cấp dịch vụ tư vấn hỗ trợ cho Khách hàng trong suốt quá trình sử dụng thông qua tổng đài tư vấn và hỗ trợ khách hàng <code>O9O32372O7</code>, email, diễn đàn và các hình thức hỗ trợ khác được công bố tại website: <a href="http://www.BKIT.com.vn" target="_blank" rel="noreferrer">http://www.BKIT.com.vn</a>.</p><p><strong>5.2.</strong> Khi sử dụng dịch vụ tư vấn qua tổng đài tư vấn và hỗ trợ khách hàng <code>O9O32372O7</code>, khách hàng chấp nhận trả cước phí điện thoại theo quy định của nhà cung cấp dịch vụ viễn thông.</p><p><strong>5.3.</strong> Khách hàng chủ động tra cứu tài liệu hướng dẫn sử dụng trực tuyến tại trang help online của sản phẩm: <a href="http://help.BKIT.VN" target="_blank" rel="noreferrer">http://help.BKIT.VN</a> hoặc tra cứu các tình huống thường gặp khi sử dụng phần mềm tại <a href="http://kb.BKIT.com.vn" target="_blank" rel="noreferrer">http://kb.BKIT.com.vn</a>.</p><p><strong>5.4.</strong> Các dịch vụ tư vấn hỗ trợ thông qua hình thức khác (như dịch vụ tư vấn hỗ trợ tại các địa điểm theo yêu cầu của khách hàng, dịch vụ tái đào tạo hướng dẫn sử dụng cho khách hàng) sẽ được hai bên thống nhất về chi phí và phương thức cung cấp bằng văn bản bổ sung khi có phát sinh yêu cầu.</p><h2 id="đieu-6-bao-hanh-bao-tri" tabindex="-1">Điều 6: Bảo hành, bảo trì <a class="header-anchor" href="#đieu-6-bao-hanh-bao-tri" aria-label="Permalink to “Điều 6: Bảo hành, bảo trì”">​</a></h2><p><strong>6.1.</strong> BKIT chịu trách nhiệm đảm bảo điều kiện kỹ thuật để khách hàng có thể sử dụng được phần mềm 24h/ngày và 7 ngày/tuần ngoại trừ thời gian bảo trì, nâng cấp, khắc phục sự cố cho hệ thống. Thời gian ngưng hệ thống để bảo trì hoặc nâng cấp hoặc sao lưu sẽ được BKIT báo trước lịch thực hiện cho khách hàng theo hình thức thông báo trực tiếp trên phần mềm. Lịch bảo trì hoặc nâng cấp hoặc sao lưu sẽ thực hiện theo định kỳ hàng ngày hoặc hàng tuần hoặc hàng tháng hoặc hàng năm và ưu tiên vào buổi đêm khi hệ thống ít sử dụng nhất.</p><p><strong>6.2.</strong> BKIT có trách nhiệm tiến hành khắc phục sự cố của hệ thống chậm nhất là 8h làm việc kể từ khi tiếp nhận được yêu cầu từ người sử dụng của khách hàng.</p><p><strong>6.3.</strong> BKIT có trách nhiệm cập nhật phiên bản mới nhất của phần mềm cho khách hàng sử dụng trong thời hạn thuê bao mà khách đã đăng ký và thanh toán cho BKIT.</p><p><strong>6.4.</strong> Khách hàng đồng ý chấp nhận tất cả sự vá lỗi, sửa lỗi, nâng cấp, bảo trì cần thiết để các tính năng của dịch vụ hoạt động chính xác và đảm bảo tính bảo mật của dịch vụ. Trừ trường hợp khẩn cấp, BKIT sẽ thông báo trước tới khách hàng lịch trình của các hoạt động sửa lỗi, nâng cấp này.</p><p><strong>6.5.</strong> Khi gần hết hạn sử dụng thuê bao phần mềm BKIT có trách nhiệm thông báo cho khách hàng trực tiếp trên chính phần mềm BKIT.VN như sau:</p><ul><li>Trong thời gian từ 60 đến 30 ngày trước khi hết hạn: Thông báo cho khách hàng biết thời hạn còn lại của thuê bao và hướng dẫn khách hàng thủ tục gia hạn thuê bao.</li><li>Trong vòng 30 ngày trước khi hết hạn: Thông báo cho khách hàng biết thời hạn còn lại của thuê bao, cảnh báo cho khách hàng biết khi hết hạn sẽ không đăng nhập để sử dụng phần mềm và hướng dẫn khách hàng thủ tục gia hạn thuê bao.</li><li>Khi hết hạn thuê bao: Hướng dẫn khách hàng thủ tục gia hạn thuê bao. Thông báo cho khách hàng biết thuê bao đã quá hạn, khách hàng sẽ không được đăng nhập để sử dụng phần mềm và nếu để quá hạn trên 30 ngày thì BKIT sẽ chính thức cắt dịch vụ, xóa bỏ dữ liệu của khách hàng.</li></ul><p><strong>6.6.</strong> Khi gần hết hạn sử dụng từng nghiệp vụ, BKIT có trách nhiệm thông báo cho khách hàng trực tiếp trên chính phần mềm BKIT.VN như sau:</p><ul><li>Trong thời gian từ 60 đến 30 ngày trước khi hết hạn: Thông báo cho khách hàng biết thời hạn còn được sử dụng của nghiệp vụ và hướng dẫn khách hàng thủ tục gia hạn nghiệp vụ.</li><li>Trong vòng 30 ngày trước khi hết hạn: Thông báo cho khách hàng biết thời hạn còn được sử dụng của nghiệp vụ, cảnh báo cho khách hàng biết khi hết thời hạn sử dụng nghiệp vụ sẽ không tiếp tục sử dụng nghiệp vụ được nữa và hướng dẫn khách hàng thủ tục gia hạn nghiệp vụ.</li><li>Khi hết hạn sử dụng nghiệp vụ: Hướng dẫn khách hàng thủ tục gia hạn nghiệp vụ. Thông báo cho khách hàng biết nghiệp vụ nào đã quá hạn, khách hàng sẽ không tiếp tục sử dụng được nghiệp vụ đó nữa.</li></ul><p><strong>6.7.</strong> Khi khách hàng sử dụng gần hết dung lượng của thuê bao, BKIT có trách nhiệm thông báo cho khách hàng trực tiếp trên chính phần mềm BKIT.VN như sau:</p><ul><li>Khi dung lượng còn trong khoảng từ 100MB đến 50 MB: Thông báo cho khách hàng biết mức dung lượng còn lại và hướng dẫn khách hàng thủ tục mua thêm dung lượng.</li><li>Khi dung lượng còn trong khoảng 50 MB: Thông báo cho khách hàng biết mức dung lượng còn lại, cảnh báo nếu khách hàng không mua thêm dung lượng thì khi hết dung lượng sẽ không nhập liệu được và hướng dẫn khách hàng thủ tục mua thêm dung lượng.</li><li>Khi hết dung lượng: Thông báo cho khách hàng biết đã hết dung lượng, khách hàng chỉ xem được dữ liệu, in được chứng từ báo cáo mà không nhập thêm mới được dữ liệu vào phần mềm.</li></ul><p>Khách hàng có thể tự chủ động tra cứu thời hạn sử dụng của thuê bao, thời hạn sử dụng của từng nghiệp vụ đã sử dụng ngay trên phần mềm theo tài liệu hướng dẫn sử dụng của phần mềm.</p><h2 id="đieu-7-dung-thu-dich-vu-free-trial" tabindex="-1">Điều 7: Dùng thử dịch vụ (Free trial) <a class="header-anchor" href="#đieu-7-dung-thu-dich-vu-free-trial" aria-label="Permalink to “Điều 7: Dùng thử dịch vụ (Free trial)”">​</a></h2><p><strong>7.1.</strong> Khách hàng tự đăng ký tài khoản dùng thử phần mềm tại website <a href="http://BKIT.VN" target="_blank" rel="noreferrer">http://BKIT.VN</a>. Khi dùng thử phần mềm BKIT.VN, khách hàng được:</p><ul><li>Sử dụng đầy đủ mọi chức năng của phần mềm;</li><li>Thời hạn sử dụng là 30 ngày;</li><li>Dung lượng sử dụng tối đa là 2GB.</li></ul><p><strong>7.2.</strong> BKIT sẽ thông báo cho khách hàng biết về thời hạn của tài khoản dùng thử như sau:</p><ul><li>Trước khi thuê bao dùng thử hết hạn 15 ngày, BKIT sẽ thông báo cho khách hàng biết về thời hạn sử dụng còn lại và hướng dẫn khách hàng làm thủ tục đăng ký dùng chính thức.</li><li>Khi hết hạn dùng thử, BKIT sẽ thông báo cho khách hàng biết thuê bao dùng thử đã hết hạn và hướng dẫn khách hàng làm thủ tục đăng ký dùng chính thức. Khách hàng sẽ không được đăng nhập để sử dụng phần mềm khi hết hạn dùng thử.</li><li>Quá hạn dùng thử trên 30 ngày, BKIT sẽ thực hiện việc cắt thuê bao và xóa bỏ dữ liệu dùng thử của khách hàng.</li></ul><p><strong>7.3.</strong> Khi khách hàng sử dụng trong thời gian dùng thử gần hết dung lượng, BKIT có trách nhiệm thông báo cho khách hàng trực tiếp trên chính phần mềm BKIT.VN như sau:</p><ul><li>Khi dung lượng còn trong khoảng từ 100MB đến 50 MB: Thông báo cho khách hàng biết mức dung lượng còn lại và hướng dẫn khách hàng thủ tục đăng ký dùng chính thức và mua thêm dung lượng để sử dụng tiếp.</li><li>Khi dung lượng còn trong khoảng 50 MB: Thông báo cho khách hàng biết mức dung lượng còn lại, cảnh báo nếu khách hàng không mua thêm dung lượng thì khi hết dung lượng sẽ không nhập liệu được và hướng dẫn khách hàng thủ tục đăng ký dùng chính thức và mua thêm dung lượng để sử dụng tiếp.</li><li>Khi hết dung lượng: Thông báo cho khách hàng biết đã hết dung lượng, khách hàng chỉ xem được dữ liệu, in được chứng từ báo cáo trong thời hạn dùng thử mà không nhập thêm mới được dữ liệu vào phần mềm. Trường hợp khách hàng xóa bớt dữ liệu đã nhập thì mới có thể nhập thêm bằng đúng số dung lượng đã xóa nếu thời hạn dùng thử thuê bao vẫn còn.</li></ul><p><strong>7.4.</strong> Khi khách hàng đăng ký sử dụng thử dịch vụ phần mềm BKIT.VN, BKIT sẽ cung cấp miễn phí dịch vụ cho khách hàng cho tới khi:</p><ul><li>Hết thời hạn dùng thử;</li><li>Khách hàng chính thức dùng dịch vụ trước khi hết hạn dùng thử.</li></ul><p><strong>7.5.</strong> BKIT không chịu trách nhiệm về bất cứ quyền lợi nào của khách hàng liên quan tới quá trình dùng thử này.</p><p><strong>7.6.</strong> Khi hết thời hạn dùng thử, toàn bộ dữ liệu dùng thử của khách hàng sẽ bị xóa bỏ khỏi hệ thống, trừ trường hợp khách hàng đăng ký chuyển sang hình thức thuê bao chính thức và được BKIT chấp nhận.</p><h2 id="đieu-8-bao-mat" tabindex="-1">Điều 8: Bảo mật <a class="header-anchor" href="#đieu-8-bao-mat" aria-label="Permalink to “Điều 8: Bảo mật”">​</a></h2><p><strong>8.1.</strong> BKIT chịu trách nhiệm thực hiện và duy trì tất cả các biện pháp bảo vệ mang tính hành chính, vật lý và kỹ thuật để bảo vệ cho tính bảo mật và toàn vẹn đối với dữ liệu khách hàng. BKIT cam kết sẽ không:</p><ul><li>Sửa đổi dữ liệu khách hàng mà không có sự đồng ý của khách hàng hoặc không phải vì mục đích khắc phục lỗi hay sự cố;</li><li>Không tiết lộ dữ liệu khách hàng trừ trường hợp phải tuân theo quy định của pháp luật hoặc được khách hàng cho phép;</li><li>Không truy cập vào dữ liệu và/hoặc làm thay đổi dữ liệu của khách hàng trừ trường hợp khắc phục lỗi kỹ thuật hoặc theo yêu cầu của khách hàng khi sử dụng dịch vụ hỗ trợ.</li></ul><p><strong>8.2.</strong> BKIT chịu trách nhiệm bảo mật mọi thông tin về dữ liệu của khách hàng và không được phép tiết lộ cho bất kỳ bên thứ ba nào khác ngoại trừ yêu cầu của cơ quan có thẩm quyền của nhà nước. BKIT không chịu trách nhiệm về các thất thoát dữ liệu, bí mật thông tin của khách hàng do khách hàng vô tình hoặc cố ý gây ra.</p><p><strong>8.3.</strong> Khách hàng chịu trách nhiệm xác định và xác thực quyền của tất cả những người dùng truy nhập vào dữ liệu của khách hàng.</p><p><strong>8.4.</strong> Khách hàng chịu trách nhiệm đảm bảo bí mật thông tin tài khoản người dùng.</p><p><strong>8.5.</strong> Khách hàng chịu trách nhiệm đối với toàn bộ các hoạt động thực hiện bởi các tài khoản người dùng của khách hàng và có trách nhiệm ngay lập tức thông báo với BKIT về các truy cập trái phép.</p><p><strong>8.6.</strong> BKIT sẽ không chịu bất cứ trách nhiệm nào liên quan đến các tổn hại gây ra bởi người dùng của khách hàng, bao gồm các cá nhân không có quyền truy cập vào dịch vụ vẫn có thể lấy được quyền truy cập do lỗi máy tính/ phần mềm hoặc hệ thống mạng nội bộ của khách hàng.</p><p><strong>8.7.</strong> Trong phạm vi của thỏa thuận này, “Thông tin bí mật” bao gồm: Dữ liệu của khách hàng, công nghệ độc quyền của mỗi bên, quy trình nghiệp vụ và các thông tin kỹ thuật của sản phẩm, thiết kế, và toàn bộ quá trình trao đổi giữa hai bên liên quan đến dịch vụ. Bất kể những điều đã đề cập ở trên, “Thông tin bí mật” không bao gồm các thông tin mà:</p><ul><li>Được công chúng biết tới;</li><li>Được biết tới trong ngành trước khi tiết lộ;</li><li>Được công chúng biết tới không phải do lỗi của bên nhận thông tin;</li><li>Dữ liệu tổng hợp trong đó không chứa bất kỳ thông tin cá nhân hoặc thông tin nào cụ thể của khách hàng.</li></ul><p><strong>8.8.</strong> Khách hàng và BKIT cùng thỏa thuận:</p><ul><li>Thực hiện các biện pháp cần thiết để giữ bí mật cho tất cả các “Thông tin bí mật”;</li><li>Không sao chép, cung cấp một phần hay toàn bộ thông tin bảo mật cho bất kỳ bên thứ ba khi chưa có sự chấp thuận của bên có quyền sở hữu đối với “Thông tin bí mật”;</li><li>Không sử dụng “Thông tin bí mật” mà các bên đã cung cấp cho nhau phục vụ cho các mục đích khác ngoài mục đích thực hiện thỏa thuận này.</li></ul><h2 id="đieu-9-ban-quyen-phan-mem-va-du-lieu" tabindex="-1">Điều 9: Bản quyền phần mềm và dữ liệu <a class="header-anchor" href="#đieu-9-ban-quyen-phan-mem-va-du-lieu" aria-label="Permalink to “Điều 9: Bản quyền phần mềm và dữ liệu”">​</a></h2><p><strong>9.1.</strong> BKIT là chủ sở hữu và có toàn quyền tác giả phần mềm BKIT.VN.</p><p><strong>9.2.</strong> Khách hàng có quyền sử dụng phần mềm để tạo ra dữ liệu phục vụ công việc của đơn vị và có quyền tải về phần dữ liệu do chính đơn vị nhập vào hệ thống trong suốt thời gian được cấp thuê bao sử dụng phần mềm.</p><p><strong>9.3.</strong> Khách hàng đồng ý rằng sản phẩm/dịch vụ, bao gồm nhưng không giới hạn: giao diện người sử dụng, đoạn âm thanh, đoạn video, nội dung hướng dẫn sử dụng và phần mềm được sử dụng để thực hiện sản phẩm/dịch vụ thuộc sở hữu riêng của BKIT được bảo hộ bởi pháp luật về sở hữu trí tuệ và quyền tác giả. Khách hàng thỏa thuận sẽ không sử dụng các thông tin hoặc tài liệu thuộc sở hữu riêng đó theo bất cứ cách thức nào ngoại trừ cho mục đích sử dụng sản phẩm/dịch vụ theo Thỏa thuận này. Không có phần nào trong sản phẩm/dịch vụ có thể được sao chép lại dưới bất kỳ hình thức nào hoặc bằng bất cứ phương tiện nào, trừ khi được cho phép một cách rõ ràng theo các điều khoản này.</p><p><strong>9.4.</strong> Khách hàng đồng ý không sửa đổi, thuê, cho thuê, cho vay, bán, phân phối, hoặc tạo ra các sản phẩm phái sinh dựa trên sản phẩm/dịch vụ theo bất cứ phương cách nào, và không khai thác sản phẩm/dịch vụ theo bất cứ phương thức không được phép nào, bao gồm nhưng không giới hạn ở việc xâm phạm hoặc tạo gánh nặng lên dung lượng của hệ thống mạng.</p><p><strong>9.5.</strong> Việc sử dụng phần mềm hoặc bất cứ phần nào của sản phẩm/dịch vụ, trừ khi việc sử dụng sản phẩm/dịch vụ như được cho phép theo thỏa thuận này, đều bị nghiêm cấm và xâm phạm đến các quyền sở hữu trí tuệ của người khác, và khách hàng có thể phải chịu các hình phạt dân sự và hình sự, bao gồm cả việc bồi thường thiệt hại bằng tiền có thể được áp dụng đối với việc xâm phạm quyền tác giả.</p><p><strong>9.6.</strong> Để BKIT có thể cung cấp dịch vụ sử dụng phần mềm cho khách hàng, khách hàng đồng ý cho BKIT quyền xử lý và truyền tải dữ liệu của khách hàng.</p><h2 id="đieu-10-pham-vi-gioi-han-trach-nhiem-cua-bkit-trong-su-dung-phan-mem" tabindex="-1">Điều 10: Phạm vi giới hạn trách nhiệm của BKIT trong sử dụng phần mềm <a class="header-anchor" href="#đieu-10-pham-vi-gioi-han-trach-nhiem-cua-bkit-trong-su-dung-phan-mem" aria-label="Permalink to “Điều 10: Phạm vi giới hạn trách nhiệm của BKIT trong sử dụng phần mềm”">​</a></h2><p><strong>10.1.</strong> BKIT có quyền nhưng không có nghĩa vụ nào trong việc thực hiện các hành động khắc phục nếu như có bất cứ nội dung nào mà khách hàng vi phạm các điều được liệt kê trong thỏa thuận này. BKIT không có bất kỳ trách nhiệm pháp lý nào đối với khách hàng trong các tình huống BKIT thực hiện hành động khắc phục. Khách hàng là người duy nhất chịu trách nhiệm về tính chính xác, chất lượng, tính toàn vẹn, hợp pháp, tin cậy và phù hợp đối với tất cả dữ liệu của mình.</p><p><strong>10.2.</strong> BKIT có thể đề nghị và khách hàng có thể lựa chọn đồng ý sử dụng các tính năng chưa được phát hành rộng rãi và chưa được kiểm duyệt hoàn toàn về mặt chất lượng theo quy trình của BKIT (các chức năng Beta). Mục đích của việc này là để khách hàng kiểm duyệt và cung cấp phản hồi cho BKIT. Khách hàng hoàn toàn chịu trách nhiệm về những rủi ro khi sử dụng các chức năng này. BKIT không đảm bảo về tính đúng đắn, đầy đủ của các chức năng Beta cũng như không chịu trách nhiệm cho các lỗi sai hoặc thiệt hại gây ra do việc sử dụng các chức năng Beta.</p><h2 id="đieu-11-thong-tin-thong-bao" tabindex="-1">Điều 11: Thông tin/ thông báo <a class="header-anchor" href="#đieu-11-thong-tin-thong-bao" aria-label="Permalink to “Điều 11: Thông tin/ thông báo”">​</a></h2><p>Trong quá trình sử dụng, Khách hàng đồng ý nhận các thông tin/ thông báo do BKIT gửi với nội dung và phương thức như sau:</p><p><strong>11.1.</strong> Nội dung các thông báo bao gồm nhưng không giới hạn bởi các loại thông tin như sau:</p><ul><li>Thông tin về các tính năng mới của sản phẩm;</li><li>Thông tin về các phiên bản mới của sản phẩm;</li><li>Thông tin về các sản phẩm có liên quan;</li><li>Thông tin về nội dung các bài báo hoặc bản tin mà BKIT cho rằng có thể hữu ích cho khách hàng trong quá trình hoạt động.</li></ul><p><strong>11.2.</strong> Phương thức gửi thông báo bao gồm nhưng không giới hạn bởi các hình thức sau:</p><ul><li>Thông báo trực tiếp trên màn hình sản phẩm;</li><li>Thông báo qua email;</li><li>Thông báo qua tin nhắn trên điện thoại di động;</li><li>Thông báo qua điện thoại;</li><li>Thông báo qua văn bản;</li><li>Thông báo bằng cách gặp trao đổi trực tiếp;</li><li>Các hình thức thông báo khác.</li></ul><h2 id="đieu-12-thong-tin-phai-sinh" tabindex="-1">Điều 12: Thông tin phái sinh <a class="header-anchor" href="#đieu-12-thong-tin-phai-sinh" aria-label="Permalink to “Điều 12: Thông tin phái sinh”">​</a></h2><p>BKIT được quyền sử dụng thông tin phái sinh từ một phần hoặc toàn bộ thông tin do khách hàng tạo ra khi sử dụng sản phẩm của BKIT để phục vụ cho các mục đích nghiên cứu cải tiến sản phẩm, thị trường, thói quen tiêu dùng và các mục đích khác có thể mang lại lợi nhuận hoặc không mang lại lợi nhuận. BKIT cam kết các thông tin phái sinh này không chứa đựng bất kể thông tin cụ thể nào về liên hệ (tên, số điện thoại, …), các giao dịch cụ thể hoặc các bí mật sản xuất kinh doanh (đã mô tả trong mục 1).</p><h2 id="đieu-13-gioi-han-trach-nhiem-phap-ly-va-thuc-hien-dich-vu" tabindex="-1">Điều 13: Giới hạn trách nhiệm pháp lý và thực hiện dịch vụ <a class="header-anchor" href="#đieu-13-gioi-han-trach-nhiem-phap-ly-va-thuc-hien-dich-vu" aria-label="Permalink to “Điều 13: Giới hạn trách nhiệm pháp lý và thực hiện dịch vụ”">​</a></h2><p><strong>13.1.</strong> BKIT không cam đoan, tuyên bố, hoặc bảo đảm rằng việc khách hàng sử dụng sản phẩm/dịch vụ của BKIT sẽ không bị gián đoạn hoặc không bị lỗi, hoặc sản phẩm/dịch vụ sẽ đáp ứng yêu cầu khách hàng hoặc tất cả các lỗi trên phần mềm và/hoặc tài liệu sẽ được sửa hoặc hệ thống tổng thể đảm bảo hoạt động của sản phẩm/dịch vụ phần mềm (bao gồm nhưng không giới hạn: mạng internet, các mạng truyền dẫn khác, mạng nội bộ và các thiết bị của khách hàng) sẽ không có virus hoặc không có thành phần gây hại.</p><p><strong>13.2.</strong> BKIT không đảm bảo dưới bất kỳ hình thức nào, dù rõ ràng hay ngầm định về các điều kiện như sự thỏa mãn về chất lượng, phù hợp cho nhu cầu sử dụng đặc thù hoặc không xâm phạm các quyền của bên thứ ba. Dịch vụ của BKIT được cung cấp cho khách hàng dưới dạng “theo hiện trạng - as is” và “có sẵn - as available” cho khách hàng sử dụng. Khách hàng sẽ chịu toàn bộ trách nhiệm trong việc xác định xem sản phẩm/dịch vụ hoặc thông tin được tạo ra từ sản phẩm/dịch vụ là đúng đắn và đáp ứng đầy đủ cho mục đích sử dụng của khách hàng.</p><p><strong>13.3.</strong> Trong bất cứ trường hợp nào BKIT đều không chịu trách nhiệm về bất kỳ các thiệt hại nào trực tiếp, gián tiếp, ngẫu nhiên, đặc biệt, hậu quả hoặc mang tính chất trừng phạt, bao gồm nhưng không giới hạn ở các thiệt hại do mất doanh thu, lợi nhuận, lợi thế kinh doanh, ngừng việc, mất mát dữ liệu do hậu quả của:</p><ul><li>Việc sử dụng hoặc không thể sử dụng sản phẩm/dịch vụ;</li><li>Bất kỳ các thay đổi nào được thực hiện đối với sản phẩm/dịch vụ;</li><li>Truy cập không được phép hoặc biến đổi các dữ liệu;</li><li>Xóa, sai hỏng, hoặc không lưu trữ dữ liệu có trên hoặc thông qua sản phẩm/dịch vụ;</li><li>Các tuyên bố hay hành vi của bất kỳ bên thứ ba nào đối với sản phẩm/dịch vụ;</li><li>Bất kỳ vấn đề nào khác liên quan đến sản phẩm/dịch vụ.</li></ul><p><strong>13.4.</strong> Trong trường hợp sản phẩm của BKIT có sử dụng dịch vụ của bên thứ ba như thông tin dự báo thời tiết, chứng khoán, tỉ giá, ..., BKIT cam kết không tính phí nhưng không đảm bảo về tính đúng sai của các thông tin trong các ứng dụng/ dịch vụ hoặc nếu bên thứ 3 có cập nhật hệ thống mà dẫn đến mất sự ổn định hoặc ngưng trệ dịch vụ. Vì vậy, người dùng phải tự cân nhắc khi sử dụng các dịch vụ này.</p><p><strong>13.5.</strong> BKIT được miễn trách nhiệm thực hiện nghĩa vụ được nêu trong thỏa thuận này đối với các trường hợp bất khả kháng ghi trong thỏa thuận này.</p><h2 id="đieu-14-trach-nhiem-xu-ly-su-co-an-ninh" tabindex="-1">Điều 14: Trách nhiệm xử lý sự cố an ninh <a class="header-anchor" href="#đieu-14-trach-nhiem-xu-ly-su-co-an-ninh" aria-label="Permalink to “Điều 14: Trách nhiệm xử lý sự cố an ninh”">​</a></h2><p><strong>14.1.</strong> Trong trường hợp khách hàng phát hiện ra các sự cố an ninh của phần mềm BKIT, khách hàng có trách nhiệm thông báo ngay với BKIT bằng cách ấn nút Phản hồi ngay trên giao diện sản phẩm hoặc gọi điện đến tổng đài <code>O9O32372O7</code>. Các sự cố an ninh phần mềm bao gồm nhưng không giới hạn bởi các trường hợp sau:</p><ul><li>Bị mất hoặc thay đổi dữ liệu trên phần mềm mà không biết nguyên nhân;</li><li>Bị gián đoạn không sử dụng được sản phẩm;</li><li>Nghi ngờ bị hacker tấn công.</li></ul><p><strong>14.2.</strong> Khi xảy ra sự cố an ninh thông tin liên quan đến sản phẩm BKIT cung cấp cho khách hàng, BKIT sẽ có trách nhiệm tổ chức điều tra để xử lý sự cố và khôi phục hoạt động cho khách hàng. Trong quá trình điều tra và khắc phục sự cố, khách hàng có trách nhiệm tham gia nếu BKIT có thể yêu cầu.</p><h2 id="đieu-15-truong-hop-bat-kha-khang" tabindex="-1">Điều 15: Trường hợp bất khả kháng <a class="header-anchor" href="#đieu-15-truong-hop-bat-kha-khang" aria-label="Permalink to “Điều 15: Trường hợp bất khả kháng”">​</a></h2><p>Trong trường hợp bất khả kháng hai bên không có nghĩa vụ phải thực hiện trách nhiệm của mình trong thỏa thuận này. Hai bên nhất trí coi các trường hợp sau là bất khả kháng:</p><ul><li>Thiên tai, địch họa gây cách trở hoặc phá hủy hoặc tắc nghẽn hoặc dừng kết nối đến trung tâm dữ liệu của BKIT;</li><li>Sự cố mất điện trên diện rộng; Sự cố đứt cáp viễn thông gây tắc nghẽn hoặc ngừng kết nối viễn thông, Internet đến trung tâm dữ liệu của BKIT;</li><li>Tin tặc (hacker), vi rút máy tính (virus) tấn công vào trung tâm dữ liệu của BKIT làm ngừng trệ, tắc nghẽn hoặc phá hủy phần mềm và dữ liệu;</li><li>Các sự cố bất khả kháng khác theo quy định của pháp luật.</li></ul><h2 id="đieu-16-tam-ngung-va-cham-dut-thoa-thuan" tabindex="-1">Điều 16: Tạm ngừng và chấm dứt thỏa thuận <a class="header-anchor" href="#đieu-16-tam-ngung-va-cham-dut-thoa-thuan" aria-label="Permalink to “Điều 16: Tạm ngừng và chấm dứt thỏa thuận”">​</a></h2><p><strong>16.1.</strong> Thỏa thuận này bắt đầu kể từ ngày khách hàng đồng ý và chấm dứt khi tất cả các thuê bao được cấp kèm theo thỏa thuận này hết hạn sử dụng. Đối với trường hợp khách hàng dùng thử sản phẩm/dịch vụ mà không chuyển sang hình thức thuê bao trước khi hết hạn dùng thử, thỏa thuận này sẽ được chấm dứt khi hết hạn dùng thử.</p><p><strong>16.2.</strong> BKIT có quyền tạm ngừng việc sử dụng của khách hàng đối với dịch vụ trong các trường hợp sau:</p><ul><li>Khách hàng không thực hiện việc đăng ký gia hạn và thanh toán các khoản chi phí sử dụng sản phẩm/dịch vụ sau khi quá hạn 60 ngày;</li><li>BKIT cho rằng dịch vụ đang được khách hàng sử dụng để tham gia vào các cuộc tấn công từ chối dịch vụ, gửi thư rác, các hoạt động bất hợp pháp hoặc việc sử dụng sản phẩm/dịch vụ của khách hàng gây nguy hại tới BKIT và những người khác.</li></ul><p><strong>16.3.</strong> Thỏa thuận được coi như chấm dứt trong các trường hợp sau:</p><ul><li>BKIT đơn phương chấm dứt thỏa thuận do Khách hàng không thực hiện nghĩa vụ thanh toán cho BKIT theo thỏa thuận giữa hai bên;</li><li>BKIT đơn phương chấm dứt thỏa thuận theo yêu cầu của tòa án và cơ quan có thẩm quyền của nhà nước;</li><li>Khách hàng gửi thông báo yêu cầu chấm dứt thỏa thuận thuê bao cho BKIT bằng văn bản.</li></ul><h2 id="đieu-17-đieu-khoan-sua-đoi-bo-sung-thoa-thuan" tabindex="-1">Điều 17: Điều khoản sửa đổi, bổ sung thỏa thuận <a class="header-anchor" href="#đieu-17-đieu-khoan-sua-đoi-bo-sung-thoa-thuan" aria-label="Permalink to “Điều 17: Điều khoản sửa đổi, bổ sung thỏa thuận”">​</a></h2><p><strong>17.1.</strong> BKIT có quyền sửa đổi, bổ sung các điều khoản trong thỏa thuận sử dụng dịch vụ và được công bố trên website <a href="https://bkit.vn" target="_blank" rel="noreferrer">https://bkit.vn</a> và trên phần mềm.</p><p><strong>17.2.</strong> Trường hợp khách hàng không đồng ý với các điều khoản sửa đổi, bổ sung đó, Khách hàng có thể ngừng sử dụng phần mềm.</p><h2 id="đieu-18-can-cu-phap-ly" tabindex="-1">Điều 18: Căn cứ pháp lý <a class="header-anchor" href="#đieu-18-can-cu-phap-ly" aria-label="Permalink to “Điều 18: Căn cứ pháp lý”">​</a></h2><p>Thỏa thuận này được soạn thảo căn cứ vào:</p><ul><li>Bộ Luật dân sự số 91/2015/QH13 ngày 24/11/2015;</li><li>Luật thương mại số 36/2005/QH11 ngày 14/6/2015;</li><li>Luật Công nghệ thông tin số 67/2006/QH11 ngày 29/6/2016;</li><li>Căn cứ vào nhu cầu của hai bên.</li></ul><h2 id="đieu-19-đieu-khoan-chung" tabindex="-1">Điều 19: Điều khoản chung <a class="header-anchor" href="#đieu-19-đieu-khoan-chung" aria-label="Permalink to “Điều 19: Điều khoản chung”">​</a></h2><p><strong>19.1.</strong> Trong quá trình thực hiện thỏa thuận nếu có vấn đề gì nảy sinh thì hai bên sẽ cùng bàn bạc, thống nhất và tìm giải pháp khắc phục.</p><p><strong>19.2.</strong> Trong trường hợp nảy sinh tranh chấp mà hai bên không thể cùng nhau thương lượng giải quyết được thì hai bên cùng thống nhất mang ra Tòa án có thẩm quyền trên địa bàn TP Hà Nội để giải quyết.</p>',127)])])}const d=n(i,[["render",o]]);export{l as __pageData,d as default};
